package com.rationportal.controller; import com.rationportal.model.FamilyMember; import com.rationportal.service.FamilyMemberService; import org.springframework.web.bind.annotation.*; import org.springframework.lang.NonNull; import java.util.List; @RestController @RequestMapping("/api/family-members") public class FamilyMemberController { private final FamilyMemberService service; public FamilyMemberController(FamilyMemberService service){this.service=service;} @GetMapping("/ration-card/{rationCardId}") public List<FamilyMember> getByRationCard(@PathVariable Long rationCardId){return service.getByRationCard(rationCardId);} @PostMapping public FamilyMember create(@RequestBody @NonNull FamilyMember member){return service.save(member);} }

